INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кашту кукурузы (кабачок ва қишқу) аз сабаби эҳтиёҷи баланд ба намнокии якхелаи реша яке аз мувофiquтарин кштҳо барои истифодаи системаҳои обории қатрагӣ ва нӯрип (ниб) мебошад. Аммо, бисёр деҳқонон дар муайян кардани <strong>масофаи нӯрип дар кштии кукуруза</strong> ва тартиби ҷойгиркунӣ суратҳои равоёнанданд. Масофаи нодуруст на танҳо дар баргирии водӣ дорад, балки сарфаҳоро зиёд мекунад ва сифати меҳварро паст меорад. Дар ин дастураи мукаммал, бо меъёрҳои фавқ ва андозаҳои чидиши ва принсипҳои амалии насби нӯрип дар боғҳои кукуруза шинос мешавад.</p>\n\n<h2>Аҳамияти дуруст муайян кардани масофаи нӯрип дар кштии кукуруза</h2>\n<p>Кукуруза рӯнаке мебошад, ки системаи решаи он сатҳӣ то ним-чуқур аст ва дар мавсими равшанӣ ба паҳншавии якхелаи об ва моддаҳои ғизоӣ дар ҳудуди кӯтоҳ (крон) эҳтиёҷ дорад. Агар <strong>масофаи нӯрип дар кштии кукуруза</strong> камтар аз ҳадди зарурӣ бошад, рақобати решаҳои ошкоро дар як равон зиёд мешавад ва ба пешсафии солим инъироб мекунад. Аз дигар сӯ, агар масофа зиёдтар аз эҳтиёҷ бошад, хароҷоти ибтидоии хариди лӯла зиёд мешавад ва қисмҳое аз хок хушк мемонанд, ки боиси нест шудани решаҳои пҳлакӣ мегардад. Мақсади чидиши дуруст, эҷоди ҳамои обории самаранок (Wetted Zone) мебошад, ки тамоми решаҳои фаъоли наботро дарбар мегирад.</p>\n\n\n\n<h2>Меъёрҳои фавқии масофаи равонҳо ва нӯрип</h2>\n<h3>Фосилаи дарози байни сафҳо (Фосилаи сафҳо)</h3>\n<p>Фосилаи байни ду сафи хурбӯ ба иқлим, навис ва усули ҷамъоварӣ вобаста аст. Аммо барои беҳтар кардани оборӣ бо банди таппӣ, маслиҳатҳои зеро одатан амалӣ мешаванд:</p>\n<ul>\n<li><strong>Кӯҳи оддӣ (нависҳои хомеҳӣ):</strong> Фосилаи сафҳо одатан аз 1 то 1.2 метр мебошад.</li>\n<li><strong>Кӯҳи саноатӣ ва механикишуда:</strong> Барои гузаштани воситаҳои ҷамъоварӣ фосилаи 1.2 то 1.5 метр тавсия дода мешавад.</li>\n<li><strong>Таъсир ба банди таппӣ:</strong> Банди таппӣ дақиқан дар миёна ё канори саф (вобаста ба навис) ҷойгир мешавад. Фосилаи байни ду банди таппӣ ба фосилаи сафҳо баробар аст. Масалан, агар фосилаи сафҳо 1.4 метр бошад, банди таппӣ низ бо фосилаи 1.4-метрӣ аз ҳам пуррароӣ дорад.</li>\n</ul>\n\n<h3>Фосилаи кабудкунии дарозайи ҳарф (Фосилаи байни наҳокиҳо)</h3>\n<p>Фосилаи байни ду наҳоки дар тӯли як ҳарф ба одамони рақобати решаҳо таъсир мерасонад. Ин фосила ба қобилияти хӯриши пуршавҳои лентаравии ройҳо таъсир мерасонад. Агар наҳокиҳо хеле наздик кӯб шаванд, минтақаҳои обёрӣ бо ҳам пурра мешаванд ва намиякӣ дар як нуқта ғайрилозим меафзояд.</p>\n<ol>\n<li>Барои нӯсҳаҳои оммавӣ, фосилаи 0.5 то 0.6 метр тавсия дода мешавад.</li>\n<li>Барои нӯсҳаҳои калон ва зудрӯшдиҳанда, фосилаи 0.7 то 0.8 метр зарур аст.</li>\n<li>Диққат диҳед, ки ҳар як пуршав бояд одамак дар radius 20 то 30 сантиметр аз решаи асосии нахоки ҷойгир бошад, то намиякӣ ба минтақаи решаҳо бирасад.</li>\n</ol>\n\n<p>Барои огоҳии бештар аз принсипҳои умумии фосилакӯбӣ дар дигар кабудҳои донбозк, ки баъзан бо қушбар кӯб мешаванд, шумо метавонед ба фосилаи лентаравии лӯбиё ишора кунед, зеро намунаи ҷойгиршавии ҳарфҳо дар ду кабуд ҳомили монанди сохторӣ аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کدو-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت کدو: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop қушбар</figcaption></figure>\n\n\n\n<h2>Таъсири ҷойгиршавии ҳарфҳо ба ҳосили қушбар</h2>\n<h3>Таъбиқ бо ҳосили ҳар гектар</h3>\n<p>Бисёр кишоварон бовар доранд, ки коҳиши фосилаи пӯлоди хурмошӯр ва зичии бештари ниҳолҳо ба таври мустақим ба зиёд шудани вазни мева оварда мерасонад. Аммо ҳақиқат ин аст, ки зичии зиёд боиси хурд шудани андозаи мева ва коҳиши сифати барои фурӯши ҳаллӣ мегардад. Дар байни фосилаи сатҳ, фосилаи дохили сатҳ ва ҳосил алоқамандии риёзии содда вуҷуд дорад:</p>\n<p>Агар ҳадафи шумо расидан ба ҳосили миёнаи миллий бошад, бояд мувозинатро байни шумораи ниҳолҳо ва хатари бемориҳои сабзакии барқарор кунед. Коҳиши фосилаи пӯлод маънои коҳиши оҳистаҳои ҳаракати ҳаво байни ниҳолҳоро дорад, ки дар минтақаҳои тар коробии меваро зиёд мекунад. Бинобар ин, <strong>Фосилаи пӯлоди хурмошӯр</strong> бояд вобаста ба шароити иқлим танзим шавад. Дар минтақаҳои хушк, мумкин аст фосиларо каме камтар (бо зичии баландтар) ба назар гирифт, аммо дар минтақаҳои тар, паҳншавии бештар лозим аст.</p>\n<p>Барои муқоисаи ҳосилотӣ, таҳқиқот <a href="https://navar-abyari.ir/melon-yield-per-hectare-guide/">Роҳнамоии ҳосили тарбузи ҳар гектар</a> мумкин аст, зеро хурмошӯр ва тарбӯз аз як оилаи растаниҳо (Cucurbitaceae) ҳастанд ва рафтори решаҳо ва минтақаи обкунӣ онҳо хеле наздик ба ҳам мебошад.</p>\n\n<h2>Қошимларро насб ва чинкунда</h2>\n<h3>Ояткаро интихоб кардан</h3>\n<p>Оятҳо бояд параллел бо сафи кӯршотон тақсим шавад. Ду усули маъмул вуҷуд дорад:</p>\n<ul>\n<li><strong>Насб дар миёни саф:</strong> Агар фосилаи дохилии саф аз 40-сантиметар камтар бошад, оятҳо миёни ду гиёҳ қарор мегирад. Ин усул барои шаклҳои зичкунанда мувофиқ аст.</li>\n<li><strong>Насб дар сарҳади саф:</strong> Агар фосилаи дохилии саф аз 50-сантиметар зиёдтар бошад, оятҳо дар як тарафи гиёҳҳо (масалан, тарафи офтоб) қарор мегирад, то ба сояандозӣ ва намнокӣ кӯмак расонад.</li>\n</ul>\n\n<h3>Хатогиҳои маъмул дар ҳисоб кардани фишор</h3>\n<p>Яке аз мушкилоти ҷидӣ дар системаҳои нӯрчаки даррӣ ин пасиши фишор дар дарозии ҷӯрҳо мебошад. Агар <strong>фосилаи нӯрчаки даррӣ барои тароб</strong> дирӯз бошад (масалан сатҳҳои 100-метрӣ), бояд одали ҷӯри асосиро ва фишори воридотро зиёд кунед. Дар ҳолати дигар, растаниҳо дар охирин сатҳ аз хӯрокнокии об барҳам мехӯрند. Тавсия мешавад, ки фишори камтар аз 0.3 бар дар нӯрчаки даррӣ истифода набаред, зеро он ба партоби об ба беруна аз минтақаи решаҳо оварда мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کدو-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت کدو: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>фосилаи нӯрчаки даррӣ тарҳбандии сатҳи ҷунб кӀукум</figcaption></figure>\n\n<p>Амалиёти насби дурусти нӯрчаки даррӣ метавонад умри муфоди системаро чанд баробар зиёд кунад. Марҳалаҳои дурусти пайвасткунӣ ва насбро дар мақолаи <a href="https://navar-abyari.ir/drip-irrigation-tape-installation-steps-ariq/">марҳалаҳои насби нӯрчаки даррӣ-қатқатӣ</a> омӯзед, то мушкилоти ибтидоӣ, ба монанди ройҳои нуруҳро пешгирӣ кардан мумкин бошад.</p>\n\n\n\n<h2>Беҳтарсозии харҷҳо ва нигоҳубин</h2>\n<p>Муайян кардани фосилаи тасмаҳои (лентҳо) барои хурма (кабӯба) на танҳо дар ҳолати ҷамъоварӣ, балки ба назорати доимӣ эҳтиёҷ дорад. Бо гузашти вақт, ҷамъ шудани отбор (осадок) дар дохили тасма метавонад боиси интилоқпалӣ (масуд шудан) дар қатрагирҳо (дрождаҳо) гардад. Фосилаи бештар байни тасмаҳо ба маънои шумораи камтари лӯлаҳо аст, аммо идоракунии лӯлаҳои тӯлонитар душвортар аст.</p>\n<ul>\n<li><strong>Арзиши шустани баръакс (печенӣ/обруиш):</strong> Системҳое, ки фосилаи стандартии 1.2 то 1.5 метрӣ доранд, одатан ба системаи тозакунии соддатар ва шустан эҳтиёҷ доранд.</li>\n<li><strong>Ғиммемар (умри) тасмаҳо:</strong> Фосилаи зиёд байни тасмаҳо сари кам шудани нуқтаҳои пайвасткунии техникивӣ, ба уҳдаи пуршуда (доимӣ) бештари лӯлаҳо аз сӯхтани (истардӣ) боиси мегардад.</li>\n</ul>\n<p>Барои дарки беҳтари буҷетакунии нигоҳдории системҳои обёрӣ, шумо метавонед мақолаи нигоҳдории тасмаҳо ва арзишҳои алоқамандро хонда бароед. Ин нуқта ба шумо кӯмак мекунад, ки таҳия кунед, оё тағйироти фосилаи тасмаҳо барои хурма барои фасли оянда аз ҷиҳати иқтисодӣ мувофиқ аст ё не.</p>\n\n<h2>Саволҳои оморат (FAQ)</h2>\n<h3>Оё имкони истифодаи тасмаҳои дуҷониба дар кӯрпашии хурма вуҷуд дорад?</h3>\n<p>Истифодаи наварҳои тиллаи дутожа (як навар дар миёнаи қатор) одатан тавсия намешавад, магар ки фосилаи байни қаторҳо хеле зиёд (зиёда аз 2 метр) бошад. Дар нақли стандартии каду истифодаи як навар тилла барои ҳар қатор идоракунии фишорро осонтар менамояд ва зонаи обориши баробартарро ба вуҷуд меорад. Тағйирот ба наварҳои дутожа ниёз ба тарҳрезии пурраи танкҳо дорад ва метавонад сабаби хориши оби гардад.</p>\n\n<h3>Беҳтарин амиқии нақли наварҳои тилла дар хокҳои вазнин чист?</h3>\n<p>Барои хокҳои рӯғунӣ наварҳои тилла бояд дар амиқии 10 то 15 сантиметр шавонда шаванд, то боздошти бухоршавии мустақимро пешгирӣ кунанд. Барои хокҳои гилӣ ва вазнин амиқии 5 то 10 сантиметр кофист, зеро гузаштагии об кам аст ва об барои сатҳи хок тезтар мемонад. Фосилаи амудии навар аз решаи асосӣ набояд аз 5 сантиметр зиёд бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-کدو-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت کدو: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop каду</figcaption></figure>\n\n<h3>Таъсири фосилаи наварҳои тилла ба хароҷоти об чӣ қадар аст?</h3>\n<p>Фосилаи нодуруст байни наварҳои тилла метавонад то 20 фоиз сабаби хориши гарди об гардад. Агар наварҳои тилла аз ҳамдигар дур бошанд, қисмҳои биёбонӣ байни қаторҳо хушк мемонанд ва деҳқон барои ҷуброн ба маҷбурият меояд, ки сарфи обро зиёд кунад, ки ин боиси оишмонии соҳаҳои решаҳо бо намак мегардад. Танзими дақиқ <strong>Фосилаи наварҳои тиллаи каду</strong> Богатари зади нақл, калиди коҳиши хароҷоти об аст.</p>\n\n<h2>Хулоса ва тавсияи ниҳоӣ</h2>\n<p>Муайян кардани фосилаи шитоби чангол дар партоб кардани каббаки як раванди дақиқи муҳандисӣ аст, ки ба фаҳмиши мутақобилаи ботаника ва хидравлика илова мекунад. Ба таври мухтасар:</p>\n<ul>\n<li>Фосилаи сафҳҳоро тибқи аврамҳои интихобшуда (одатан 1,2 то 1,5 метр) собит кунед.</li>\n<li>Шитоби чанголро чунин насб кунед, ки ҳадди аксар 30 сантиметри решаи асосиро пӯшад.</li>\n<li>Аз фишурдагӣи зиёдатии сафҳҳоро дар минтаҳоинамдоди пайдарпайи хомҳамаддорӣ дурӣ ниҳед.</li>\n<li>Нигоҳдории давравии системаро тибқи фосилаҳои муайяншуда барнома кунед.</li>\n</ul>\n<p>Барои пурра кардани маълумоти худ дар самти принсипҳои умумии обкорӣ ва зиёд шудани истеҳсолот, таҳқиқот дар бораи ҳаҷми оби кӯл ва обкорӣ дар гектар метавонад диди кураштакиро дар сохтори захиҳои обии кӯлакони шумо ба вуҷуд орад. Бо риояи ин принсипҳо, на танҳо сифати каббакҳои истеҳсолшударо меафзояд, балки аз ҳаҷми лозимии обкорию низ сарфамол мекунед.</p>\n<p><strong>Маводи марбут:</strong> <a href="https://navar-abyari.ir/%D9%81%D8%A7%D8%B5%D9%84%D9%87-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%AF%D8%B1-%D9%84%D9%88%D8%A8%DB%8C%D8%A7/">D981D8A7D8B5D984D987 D986D988D8A7D8B1 D8AADB8CD9BE D8AFD8B1 D984D988D8A8DB8CD8A7</a>. <a href="https://navar-abyari.ir/garlic-seed-per-hectare-factors-increase-37460-2/">garlic seed per hectare factors increase 37460 2</a></p>','Фосилаи қатори типӣ дар нақили кӯко: стандартҳои тавсияшуда','Муайян кардани масофаи мувофқи нақшаи чинги ҳангоми кардани кӯкибонӣ барои беҳтар кардани истифодаи об ва зиёд кардани ҳосил муҳим аст. Дар ин дастур, принсипҳои ҷойгиршавии сатҳҳо, масофаҳои стандарти ва нуқтаҳои амалӣ баррасӣ мешаванд.','publish','closed','closed','fasila-i-qatori-tipi-dar-naquli-koko',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
