INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррарот: Чаро барои сабзӣ системаи лентаронӣ?</h2>\n<p>Корзири сабзӣ ба сабаби ҳассосии решаҳои он ба хушкӣ ва ниёз ба обдиҳии якхела яке аз мураккабтарин равандҳои кишоварӣ ҳисоб мешавад. Дар солҳои охир истифодаи <strong>лентаронӣ</strong> ҳамчун ивазкунанда барои қатқатҳои анъанавӣ диққати бисёре аз кишоваронро ба худ кашидааст. Агар пурсед <strong>хароҷоти кори сабзӣ бо лентаронӣ дар гектар</strong> чӣ қадар аст, бояд донед, ки ин система бо кам шудани хароҷоти насб, истеъмоли энергияи помпагоронӣ ва талафоти об, метавонад самаранокии иқтисодиро ба таври эҳсосӣ зиёд кунад.</p>\n<p>Дар ин дастурҳои ҷамъбаست, ғайр аз таҳлили хароҷоти мувоқиф ва гумӯҳам, ба чӣ гуна интихоби дуруст масофаи пиёз ва намуди лентаронӣ барои шаклҳои гуногуни сабзӣ низ мерасем. Мароҳи мо ин аст, ки шумо тавонед ҳалли фаҳмонандаро дошта бошед ва аз хатогиҳои оддӣ дар системаҳои муосири обориш пешгирӣ кунед.</p>\n\n[IMAGE_1]\n\n<h2>Таҳлили хароҷоти серкарда: бода, чӯр ва таҷҳизот</h2>\n<p>Қисми аввали таъиноти буҷа барои кишт, ки хариди тоқӣ ва таҷҳизоти ибтидоиро дар бар мегирад, мебошад. Нархи тоқии карду вобаста ба насбҳои дохилӣ ва хориҷӣ ва сифати он гуногун аст. Барои кишт бо зичии мувофиқ дар системаи рибони дариллӣ одатан аз зичии ғавросии 35 то 45 килограмм тоқӣ дар ҳектар истифода мебаранд. Ҳамчунин, ғайр аз тоқӣ, хараҷоти омодакунии моддаҳои заҳрнок барои назорати ибтидоии зараррасонҳо ва хариди симҳо барои устувории рибони дариллӣ низ бояд назардошуда шаванд.</p>\n<h3>Нуқтаҳои муҳим дар интихоби тоқӣ ва фосилаи кишт</h3>\n<ul>\n<li><strong>Фосилаи сатҳҳо:</strong> Дар системаи рибони дариллӣ, фосила байни сатҳҳои кишт бояд бо андозаи паҳши рибон мувофиқат кунад, то партобиши решаҳо пурра бошад.</li>\n<li><strong>Навъи хок:</strong> Дар хокҳои санг, фосилаи ғавросии зичтар мувофиқтар аст, аммо дар хокҳои сазумӣ, барои инкишофи решаҳо фазои бештар лозим аст.</li>\n<li>Барои муқоисаи сарфи тоқӣ дар сабзавотҳои дигар, шумо метавонед роҳнамои <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%ae%db%8c%d8%a7%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/" target="_blank" rel="noopener">Миқдори тоқии хурмо дар ҳектар</a> баррасед, ки ба принсипҳои пардакшонии чукка монандиҳо дорад.</li>\n</ul>\n\n<h2>Арзиши системаи оромандӣ: сармоягузорӣ дар навори пип (Drip Tape)</h2>\n<p>Қисми асосии <strong>арзиши корҳои кадомии чукка бо навори пип дар ҳектар</strong> ба худ системаи оромандӣ махсус карда шудааст. Навори пипҳо (Drip Tape) ба ду навъ, собит ва истеъмолшаванда (detachable) вуҷуд доранд. Барои парвариши солӣ монанди чукка, ки пас аз каморӣ аз замин бардошта мешавад, истифодаи навори пипҳои истеъмолшаванда тавсия мешавад, зеро имконияти шустушӯ ва такрорро дар соли оянда фароҳам меоранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-هویج-با-نوار-تیپ-در-هکتار-تصویر-شاخص.webp" alt="هزینه کشت هویج با نوار تیپ در هکتار - تصویر 1"/><figcaption>crop cost per hectare drip tape чукка</figcaption></figure>\n<h3>Қисмҳои ташкилкунандаи арзиши насб</h3>\n<ol>\n<li><strong>навори пип пластикӣ:</strong> Арзиш аз рӯйи метри нӯл ва ғафсии девор ҳисоб мешавад. Ғафсии 70 микрон одатан барои як даврони кӣш мувофиқ аст.</li>\n<li><strong>Синкер (созанда) ва филтр:</strong> Ҳифзи нӯл аз отлакиш ва алаф.</li>\n<li><strong>Лӯлаҳои асосӣ ва шохаҳо:</strong> Барои тақсими баробари фишор дар тӯли майдон.</li>\n<li><strong>Арзиши корубори насб:</strong> Насби дақиқи нӯли чӯкандӣ ба дақиқии техникий лозим дорад, то сӯрохҳо зери сатҳи хок ҷойгир нашаванд.</li>\n</ol>\n<p>Барои фаҳмиши беҳтари намудҳои ин системаҳо, мақола <a href="https://navar-abyari.ir/%D8%A7%D9%86%D9%88%D8%A7%D8%B9-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/" target="_blank" rel="noopener">Навидҳои нӯриб</a> ро омӯзед, то фарқияти фаннӣ-техникии ҳар яке-ро донед. Ғайр аз ин, агар шумо комбинатсияи обёрӣ-капулӣ ва боронро дар назар дошта бошед, нӯриб-фатҳе ва комбинатсионӣ (Fixed Spray Tape) метавонад барои як қатори кӯрҳаҳои омехта вариант муассир бошад.</p>\n\n[IMAGE_2]\n\n<h2>Сарфи об ва энергия: Камаҳмии расмҳои ҷорӣ</h2>\n<p>Яке аз сабабҳои асосӣ барои интихоби нӯриб кам шудани сарфи об аст. Дар ҳоле ки обёрӣ-саҳи дар минтақаҳои биёабонӣ то 40 фоизи обро гум мекунад, системаи нӯриб бо обёрӣ-мустақим ба минтақаи реша, ин хоборо ба ҳадди ақал мерасонад. Аз наظари расм, кам шудани сарфи об маънои кам шудани сарфи помпа ва нерӯи баро дорад.</p>\n<h3>Фарқият дар расмҳои энергия</h3>\n<ul>\n<li><strong>Помпа:</strong> Ғафсати кории нӯриб одатан пасттар аз каппи-ризиш-мудир аст, ки ба фоида кам шудани расмҳои помпа ва кам шудани вайронии таҷҳизот аст.</li>\n<li><strong>Гуруҳи амалиётӣ:</strong> Бо насби худкори лентаи ҷаминӣ, дар марҳилаи обёрӣ ниёз ба кӯшиши инсонӣ камтар мешавад.</li>\n<li>Барои ҳисобкунии дақиқтар, шиносӣ бо <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%aa%d8%b1%db%8c%d8%aa%db%8c%da%a9%d8%a7%d9%84%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/" target="_blank" rel="noopener">миқдори тоҳи тритикала дар як гектар</a> Ин фарқиятҳои идоракунӣ байни маҳсулотҳои гуногунро нишон медиҳад, гарчанде ки карам ба гурӯҳи сабзевии риштадор мерасад.</li>\n</ul>\n\n<h2>Таъсири лентаи ҷаминӣ ба самаранокии ва сифати маҳсулот</h2>\n<p>Сифати карам бевосита бо якхелии обёрӣ пайваст аст. Лентаи ҷаминӣ тавассути тақсимоти якхелаи об ва тазмини моддаҳои ғизоӣ (fertigation) дар ҳудуди решаҳо, рушди ҳамзамон ва якхелаи карамҳоро ба вуҷуд меорад. Ин боиси зиёдшавии дараҷаи тиҷоратии маҳсулот ва камшавии заҳолӣ дар марҳилаи бастабандӣ мегардад.</p>\n<p>Илова бар ин, назорати отаҳо дар байни сатҳҳо ба сабаби хушк мондани замин дар сатҳ дар системаҳои қатрагӣ душвортар аст; аммо лентаи ҷаминӣ бо кам кардани сатҳи намдории растани, муқовимат ба бемориҳои зангиро баланд мебардорад ва ниёз ба зарб задани дорҳои бисёрро кам мекунад, ки ҳаҷми хараҷи дорро баргашта медиҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-هویج-با-نوار-تیپ-در-هکتار-کاربرد-عملی.webp" alt="هزینه کشت هویج با نوار تیپ در هکتار - تصویر 2"/><figcaption>crop cost per hectare drip tape карам</figcaption></figure>\n\n[IMAGE_3]\n\n<h2>Роҳнамои амалӣ ва нуқтаҳои техникӣи нигоҳубин</h2>\n<p>Барои нигоҳ доштани умри кории система ва идомаи рентаблии иқтисодӣ, риояи нуқтаҳои зерин зарур аст:</p>\n<ol>\n<li><strong>Фишори устувор:</strong> Нигоҳ доштани фишори система дар ҳудуди тавсияшуда (одатан 1 то 2 бар) барои паҳншавии баробари об муҳим аст.</li>\n<li><strong>Шустани филтрҳо:</strong> Филтри дискӣ ё торӣ бояд ҳар ҳафтаро таҳқӣқ ва шуста шавад, то кушодҳои навор банд нашавад.</li>\n<li><strong>Даромади мувофик:</strong> Ҳеми даромад, ҳангоги даромади резид, эҳтиёт бошед, ки навори тиб пачад набошад ё ғам набошад, зеро таъмири он нарх дорад.</li>\n<li>Барои дароз кардани умри фаъоли система ва истифодаи дубораи нарв, ҳатман мақолаи роҳи дароз кардани умри файдии нарви типро муталлаҳ кунед. Ин раванд метавонад сарфашавии солнаро то 50 фоиз коҳиш диҳад.</li>\n</ol>\n<p>Бинобар ин, агар нақшаи парҳези омехта бо дигар маҳсулотро дошта бошед, масалан <a href="https://navar-abyari.ir/fasoolia-yield-per-hectare-iraq/" target="_blank" rel="noopener">самаранокии фасулӣ (нуху) дар гектар</a> -ро баррасӣ кунед, то муносибатҳои байни маҳсулотро идора намоед.</p>\n\n<h2>Саволҳои зиёд такроршаванда (FAQ)</h2>\n<h3>Оё нарви типро барои хокҳои вазнин истифода бурдан мумкин аст?</h3>\n<p>Бале, аммо бояд аз нарвҳо бо сӯрохҳои калонтар ва ҷараёни баландтар истифода баред, то аз пӯсиши зуд ба сабаби омадани зарм ва лой пешгирӣ шавад. Дар ин ҳолат, сармоягузории ибтидоӣ каме баландтар аст, аммо самаранокии дарозмуддат якхела аст.</p>\n<h3>Нарви типрӣ чанд сол тоб меорад?</h3>\n<p>Фиттонҳо дар шакли лангаромаднок одомадатан барои истифода 3 то 5 сол бо нигоҳубинии дуруст мувофиқ мебошанд. Пас аз ин, шустушуви дохилӣ ва санҷиши дақиқӣ тавсия дода мешавад. Истифодаи филтрҳои мувофиқ калиди асосии устувории система мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-هویج-با-نوار-تیپ-در-هکتار-جزئیات-فنی.webp" alt="هزینه کشت هویج با نوار تیپ در هکتار - تصویر 3"/><figcaption>crop cost per hectare drip tape ҳавуч</figcaption></figure>\n<h3>Нархи парвариши ҳавуч бо фиттонҳои чангоришаванда барои як гектар бо нархи фишоришуда чӣ хил муносибат дорад?</h3>\n<p>Гарчанде ки сарфнокии анборкунии ибтидоии фиттонҳо метавонад аз қуттичакҳо камтар бошад, вале сарфнокии умумии парвариш (шоми об, энергия ва кор) аз сабаби коҳиш ёфтани талафот ва зиёд шудани самаранокии кор, одомадатан 15 то 20 фоиз фаъолтар аст.</p>\n\n<h2>Хулосабарорӣ ва маслиҳатҳои охирин</h2>\n<p>Старҳии системаҳои обёрӣ муосир, монанди фиттонҳо, хатарҳои парвариши сабзавотҳои ҳассостаро кам мекунад. Гарчанде ки ҳисоби дақиқи сарфнокӣ <strong>Нархи парвариши ҳавуч бо фиттон барои як гектар</strong> бо тағйирёбандаҳои иқлимӣ ва нархҳои лаҳзавӣ вобаста аст, вале қоидаҳои устувори ин система, яъне самаранокӣи баланд ва сардории энергия, онро ба вариантҳои беҳтар барои кишоварзии пурмеҳнат табдил додааст. Бо риоя кардани қоидаҳои нигоҳубинӣ ва интихоби дақиқи таҷҳизот дар асоси намуди хок ва навъи ҳавуч, метавонед умедвор бошед ба самаранокӣи иқтисодии беҳтар.</p>\n<p>Пешниҳоди охирини мо ин аст, ки пеш аз насб, аз як муҳendisи ихтисоси обёрӣ машораот гиред, то фосилаи сатҳҳо ва фосилаи пикҳо банди навузро дақиқан ба шароити заминатонатон мутобиқ кунад. Муваффақият дар ҳосилкоришкунӣи карам, омехтаи дониши техникӣ ва идоракунии молиявии ҳошияст.</p>','Маблағи ғунҷонидани морқав қаламча бо нарди: Раҳнамои иқтисодӣ ва техникӣ барои ҳектар','Дар ин мақола мо таносухи пурраи ҳарҷаҳои парҳезии сабзи чормағзон бо усули нафр банду бар ҳар гектарро баррасӣ мекунем. Аз сархати дастӣ то асосҳои амалӣ барои нигоҳубини нафр банд ва таъсираш дар афзоиши самаранокии mahсулотҳои решагӣ, бо ҷадвалҳои муқоисавӣ ва ҷавобҳо ба саволҳои такроршудаи деҳқонон.','publish','closed','closed','mazmuni-kushish-ghunjonidani-morqav-qalamcha',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
